 function begin(){player.x=2.5;player.y=2.5;player.a=0;player.hp=100;player.armor=75;player.ammo=24;player.reserve=120;enemies=initialEnemies.map((e,i)=>({...e,hp:100,alive:true,attack:1.3+i*.3,alert:false,phase:Math.random()*6}));shots=0;hits=0;started=true;ended=false;$('intro').classList.add('hidden');$('result').classList.add('hidden');$('phase').textContent='ELIMINATE HOSTILES';showToast('HOSTILE CONTACT — CLEAR THE SITE');updateHud()}
 $('startBtn').addEventListener('click',begin);$('againBtn').addEventListener('click',begin);
